from pathlib import Path
import json,hashlib,subprocess
p=Path(__file__).resolve().parent
h=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
def write(n,obj):
 text=obj if isinstance(obj,str) else json.dumps(obj,indent=2)
 subprocess.run(['python3','-I','-B',str(p/'write_lane.py'),n],input=text,text=True,check=True)
mods=json.loads((p/'production-modules.json').read_text())
receipts=[]
for q in sorted((p/'receipt').glob('*.json')):
 r=json.loads(q.read_text()); assert not r.get('group_members_left'),q
 receipts.append(dict(path=str(q.relative_to(p)),sha256=h(q),label=r['label'],exit=r['exit'],log=r['log'],log_sha256=r['log_sha256'],guard=r['guard'],group_members_left=r['group_members_left']))
records=[]
for m in mods:
 src=p/'src'/(m+'.lean'); ext=p/'replay/src'/(m+'.lean')
 assert h(src)==h(ext)
 runs={k:[r for r in receipts if r['label']==k+'_'+m] for k in ['lean','leanchecker','replay_lean','replay_checker']}
 assert all(v and v[-1]['exit']==0 for v in runs.values()),m
 records.append(dict(module=m,source_sha256=h(src),extracted_source_sha256=h(ext),working_olean_sha256=h(p/'build'/(m+'.olean')),post_checker_replay_olean_sha256=h(p/'replay/build'/(m+'.olean')),runs=runs))
write('results/REPLAY.json',dict(initial_build_empty=True,source_only=True,module_count=len(mods),production_order=mods,records=records,exclusions=['NegativeSameSide: intentional false semantic control, exit1','RealConversionProbe and TVProbe: historical failed API probes','ShoeDeepAudit: three failed memory-limited whole-environment audit attempts, exit-6'],scope='All 20 production proof/control/named-audit modules only. Full failed body audit is not replay-paid.'))
newpaid=['Exact isolated-event cylinder probability p_i^2 (1-p_i)^(2K-2)','Four-coordinate competing-pair estimate and unconditional finite union bound','Measurable disjoint GoodBlock sum into actual winningLaw','Positive real collision mass, coordinate square-root, floor scale and Bernoulli bridges','Actual winningLaw minorization by pairLaw/256 in all branches','Countable absolute convergence, overlap and positive-part TV identities','PMF-to-measure indicator sum, arbitrary Nat-subset supremum identity and attaining subset','Conditional sourceX and actual sourceY with almost-sure fallback removal in endpoint','Uniform source-Nat supremum <=255/256<1','Clean isolated semantic negative control and positive controls','20 production modules strict+checker and source-only empty-build strict+checker replay','Readable report PDF, all three final pages visually inspected']
unpaid=['General arbitrary-countable color relabeling and finite zero-extension invariance certificates; source Nat model is checked including zeros and infinite support','Whole-environment including private/generated/transitive body-origin DAG and per-endpoint body closures: three attempts exit -6 memory exceptions under -M3500','Independent final source-to-Lean/proof/deep-body/manuscript review','Root acceptance and credit adjudication']
prev=json.loads((p/'inputs/previous/results/CHECKPOINT.json').read_text())
deviations=prev['deviations']+['Initial current-turn receipt/log display used uncapped Python outside runner; retained transcript. Later displays under exact immutable runner CLI mirror saved bounded output to parent stdout.','Several early mandatory output dumps truncated; relevant source/proof mathematical passages recovered, bulk receipt metadata machine-read and preserved rather than all personally displayed.','A leanchecker invocation followed failed ShoeBlockSum compilation; failed exit1 preserved and successful checker followed repair.','Audit tool-session ID was omitted from one displayed tool result; no new compiler started until runner fixed cap had elapsed.','Orchestration-only JavaScript errors before execution changed no files.','Reportlab unavailable; groff pdf device and ms macro package unavailable; failed commands retained. Plain roff plus PostScript conversion succeeded. Initial rendering had clipping; regenerated with bottom trap and heading keep, visually inspected final three pages.','Renderer was invoked after failed PDF creation twice; failed true exit receipts retained.']
d=dict(mathdb_id=324571,status='CHECKED_NAT_ENDPOINT_WITH_UNPAID_GATES_NOT_TECHNICAL_PASS',credit=0,campaign='55/60 beyond39prior',accepted=False,formal_endpoint='Shoe.source_strict_universal_supremum',formal_endpoint_file='src/ShoeEndpoint.lean',formal_endpoint_source_sha256=h(p/'src/ShoeEndpoint.lean'),paid_inherited=prev['paid'],paid_new=newpaid,unpaid=unpaid,latest_strict_exit=0,latest_checker_exit=0,production_module_count=len(mods),replay='results/REPLAY.json',named_endpoint_axiom_union=['propext','Classical.choice','Quot.sound'],deep_body_audit='FAILED_MEMORY_THREE_ATTEMPTS',controls=dict(positive='ShoeSemanticControls strict+checker0',negative='NegativeSameSide expected exit1, sole unsolved False goal'),paper='output/pdf/shoe-discrepancy-report.pdf',paper_pages_visually_inspected=[1,2,3],prior_limits=['Galbraith-Holmes2012 body404/unread; no worldwide novelty claim','All inherited denials binding, no network performed'],deviations=deviations,completed_receipts=receipts,all_recorded_groups_empty=True,resource_scope='Immutable runner per-group CPU/wall/AS caps and sampled RSS; not global cgroup telemetry')
write('results/CHECKPOINT.json',d)
